const input = $json;
const jobs = Array.isArray(input.jobs_raw) ? input.jobs_raw : [];

const pick = (...v) => v.find((x) => x !== undefined && x !== null && x !== '');
const arr = (v) => (Array.isArray(v) ? v : []);
const strArr = (v) => arr(v).map((x) => (typeof x === 'string' ? x : JSON.stringify(x))).filter(Boolean);

const normalized = jobs.map((j) => {
  const linkedinUrl = pick(j.jobUrl, j.link, j.url, '');
  const jobId = pick(j.jobId, j.id, (linkedinUrl.match(/currentJobId=(\d+)/) || [])[1], '');
  const parsed = j.locationParsed || j.parsed || {};

  return {
    job_id: jobId,
    title: pick(j.title, j.jobTitle, ''),
    company_name: pick(j.companyName, j.company?.name, ''),
    company_linkedin: pick(j.companyUrl, j.company?.linkedinUrl, ''),
    company_website: pick(j.companyWebsite, j.company?.website, ''),
    location_text: pick(j.location, j.formattedLocation, ''),
    country: pick(j.countryCode, parsed.countryCode, parsed.country, ''),
    state: pick(parsed.state, parsed.region, ''),
    city: pick(parsed.city, ''),
    workplace_type: pick(j.workplaceType, ''),
    employment_type: pick(j.employmentType, ''),
    experience_level: pick(j.experienceLevel, ''),
    posted_date: pick(j.postedDate, j.postedAt, ''),
    expiry_date: pick(j.expireAt, j.expiryDate, ''),
    applicant_count: pick(j.applicantCount, j.applicationsCount, ''),
    job_url: linkedinUrl,
    easy_apply_url: pick(j.applyUrl, j.easyApplyUrl, ''),
    description: pick(j.description, j.descriptionText, ''),
    salary_text: pick(j.salary, j.salaryText, ''),
    industries: strArr(j.industries),
    job_functions: strArr(j.jobFunctions),
    company_size: pick(j.company?.size, j.companySize, ''),
    company_followers: pick(j.company?.followers, j.companyFollowers, ''),
    apply_method_type: pick(j.applyMethodType, ''),
    ats_system: pick(j.ats, j.atsSystem, ''),
    scraped_at: new Date().toISOString(),
    actor_run_id: input.actor_run_id,
    dataset_id: input.dataset_id,
    search_name: input.search_name,
    raw_json: j
  };
});

return normalized.map((json) => ({ json }));

const targetCountry = String($env.COUNTRY_FILTER_DEFAULT || 'IN').toUpperCase();

return $input.all().map((item) => {
  const j = item.json;
  const countryRaw = String(j.country || '').trim().toUpperCase();
  const locationRaw = String(j.location_text || '');

  const map = {
    INDIA: 'IN',
    IN: 'IN',
    USA: 'US',
    UNITED STATES: 'US'
  };

  const normalizedCountry = map[countryRaw] || countryRaw;
  const regexIndia = /\b(india|bengaluru|bangalore|hyderabad|pune|gurgaon|noida|mumbai|delhi|chennai)\b/i;
  const fallbackIn = regexIndia.test(locationRaw) ? 'IN' : normalizedCountry;
  const effective = fallbackIn;

  const accepted = effective === targetCountry;
  j.country = effective;
  j.filter_stage = 'country_filter';
  j.filter_reason = accepted ? 'accepted' : `country_mismatch:${effective}`;
  j.is_rejected = !accepted;
  return { json: j };
});

const simpleHash = (s) => {
  let h = 0;
  for (let i = 0; i < s.length; i += 1) {
    h = ((h << 5) - h) + s.charCodeAt(i);
    h |= 0;
  }
  return String(Math.abs(h));
};

return $input.all().map((item) => {
  const j = item.json;
  const normalizedUrl = String(j.job_url || '').trim().toLowerCase();
  const composite = `${String(j.title || '').trim().toLowerCase()}|${String(j.company_name || '').trim().toLowerCase()}|${String(j.location_text || '').trim().toLowerCase()}`;

  j.dedupe_key_job_id = String(j.job_id || '').trim();
  j.dedupe_key_url = normalizedUrl;
  j.dedupe_key_hash = simpleHash(composite);
  j.processing_status = 'NEW';
  j.date_created = new Date().toISOString();
  return { json: j };
});
